draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Philosopher-king
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 - 30, H/2 + 130);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(W/2 + 30, H/2 + 130);
  ctx.stroke();

  // Book
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Republic', W/2, H/2 - 70);

  // Justice scale
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 200);
  ctx.lineTo(W/2 + 100, H/2 + 200);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 + 200, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 200, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '18px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Virtue', W/2 - 50, H/2 + 230);
  ctx.fillText('Vice', W/2 + 50, H/2 + 230);

  // Ideal state
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Kallipolis', W/2, H - 50);

  // Animation
  ctx.save();
  ctx.translate(W/2, H/2);
  ctx.rotate(Math.sin(t));
  ctx.beginPath();
  ctx.moveTo(0, -50);
  ctx.lineTo(-30, -70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(0, -50);
  ctx.lineTo(30, -70);
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}
